div.script:

document.title = "dormo.io";

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const fov = 400;
const cx = canvas.width / 2;
const cy = canvas.height / 2 - 40;

let player = {
  x: 0,
  z: 0,
  dx: 2.5,
  dz: 0,
  radius: 16,
  trail: []
};

// AI Bot Opponents
let bots = [
  { x: -150, z: -100, dx: 0, dz: 2, color: '#ef4444', radius: 14, trail: [], timer: 0 },
  { x: 150, z: 100, dx: -2, dz: 0, color: '#22c55e', radius: 14, trail: [], timer: 0 },
  { x: -150, z: 100, dx: 2, dz: 0, color: '#eab308', radius: 14, trail: [], timer: 0 }
];

let score = 0;

window.addEventListener('keydown', e => {
  if ((e.key === 'ArrowUp' || e.key === 'w') && player.dz === 0) { player.dx = 0; player.dz = -2.5; }
  if ((e.key === 'ArrowDown' || e.key === 's') && player.dz === 0) { player.dx = 0; player.dz = 2.5; }
  if ((e.key === 'ArrowLeft' || e.key === 'a') && player.dx === 0) { player.dx = -2.5; player.dz = 0; }
  if ((e.key === 'ArrowRight' || e.key === 'd') && player.dx === 0) { player.dx = 2.5; player.dz = 0; }
});

function project(x, y, z) {
  const tiltY = y - 250; 
  const scale = fov / (fov + z + 100);
  return {
    x: cx + x * scale,
    y: cy + tiltY * scale,
    scale: scale
  };
}

function update() {
  // Update Player
  player.x += player.dx;
  player.z += player.dz;

  if (player.x < -250) player.x = 250;
  if (player.x > 250) player.x = -250;
  if (player.z < -200) player.z = 200;
  if (player.z > 200) player.z = -200;

  if (Math.random() < 0.2) {
    player.trail.push({x: player.x, z: player.z});
    if (player.trail.length > 180) player.trail.shift();
    score = Math.min(100, Math.floor(player.trail.length * 0.6));
    document.getElementById('scoreDisplay').textContent = "Territory Captured: " + score + "%";
  }

  // Update AI Bots
  bots.forEach(bot => {
    bot.x += bot.dx;
    bot.z += bot.dz;
    bot.timer++;

    // Random turning behavior for AI bots
    if (bot.timer > 60 + Math.random() * 60) {
      bot.timer = 0;
      const dirs = [
        {dx: 2, dz: 0}, {dx: -2, dz: 0},
        {dx: 0, dz: 2}, {dx: 0, dz: -2}
      ];
      const newDir = dirs[Math.floor(Math.random() * dirs.length)];
      bot.dx = newDir.dx;
      bot.dz = newDir.dz;
    }

    if (bot.x < -250) bot.x = 250;
    if (bot.x > 250) bot.x = -250;
    if (bot.z < -200) bot.z = 200;
    if (bot.z > 200) bot.z = -200;

    if (Math.random() < 0.25) {
      bot.trail.push({x: bot.x, z: bot.z});
      if (bot.trail.length > 120) bot.trail.shift();
    }
  });
}

function drawGrid3D() {
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 1.2;

  const step = 40;
  const xLimit = 250;
  const zLimit = 200;

  for (let i = -xLimit; i <= xLimit; i += step) {
    let p1 = project(i, 0, -zLimit);
    let p2 = project(i, 0, zLimit);
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.stroke();
  }

  for (let i = -zLimit; i <= zLimit; i += step) {
    let p3 = project(-xLimit, 0, i);
    let p4 = project(xLimit, 0, i);
    ctx.beginPath();
    ctx.moveTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.stroke();
  }
}

function draw() {
  ctx.fillStyle = '#0b0f19';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  drawGrid3D();

  // Draw Bot Trails & Bots
  bots.forEach(bot => {
    bot.trail.forEach(t => {
      const p = project(t.x, 0, t.z);
      if (p.scale > 0) {
        ctx.fillStyle = bot.color;
        ctx.fillRect(p.x - (7 * p.scale), p.y - (7 * p.scale), 14 * p.scale, 14 * p.scale);
      }
    });

    const bp = project(bot.x, 0, bot.z);
    if (bp.scale > 0) {
      ctx.fillStyle = bot.color;
      ctx.beginPath();
      ctx.arc(bp.x, bp.y, bot.radius * bp.scale, 0, Math.PI * 2);
      ctx.fill();
    }
  });

  // Draw Player Territory Trail
  player.trail.forEach((t) => {
    const p = project(t.x, 0, t.z);
    if (p.scale > 0) {
      ctx.fillStyle = '#f97316';
      ctx.fillRect(p.x - (8 * p.scale), p.y - (8 * p.scale), 16 * p.scale, 16 * p.scale);
    }
  });

  // Draw Player (Overhead 3D Smiley Face)
  const p = project(player.x, 0, player.z);
  if (p.scale > 0) {
    const r = player.radius * p.scale;

    ctx.fillStyle = '#f97316';
    ctx.beginPath();
    ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ea580c';
    ctx.lineWidth = 2 * p.scale;
    ctx.stroke();

    const eyeSize = Math.max(2, 3.5 * p.scale);
    ctx.fillStyle = '#7c2d12';
    ctx.fillRect(p.x - 5 * p.scale, p.y - 4 * p.scale, eyeSize, eyeSize);
    ctx.fillRect(p.x + 3 * p.scale, p.y - 4 * p.scale, eyeSize, eyeSize);

    ctx.strokeStyle = '#7c2d12';
    ctx.lineWidth = 1.5 * p.scale;
    ctx.beginPath();
    ctx.arc(p.x, p.y + 2 * p.scale, 4 * p.scale, 0, Math.PI, false);
    ctx.stroke();
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
